from typing import List

def articulationPoints(V: int, adj: List[List[int]]) -> List[int]:
    if V == 1:
        return [-1]

    # Build adjacency list and remove self-loops (though P3 says no self-loops)
    adj_list = [[] for _ in range(V)]
    for u in range(V):
        for v in adj[u]:
            if u != v:
                adj_list[u].append(v)

    time = 0
    discovery = [-1] * V
    low = [-1] * V
    visited = [False] * V
    is_articulation = [False] * V

    def dfs(u, parent):
        nonlocal time
        children = 0
        visited[u] = True
        discovery[u] = low[u] = time
        time += 1

        for v in adj_list[u]:
            if not visited[v]:
                children += 1
                dfs(v, u)
                low[u] = min(low[u], low[v])

                # Check for articulation point
                if parent != -1 and low[v] >= discovery[u]:
                    is_articulation[u] = True
            elif v != parent:
                low[u] = min(low[u], discovery[v])

        # Root case
        if parent == -1 and children > 1:
            is_articulation[u] = True

    for u in range(V):
        if not visited[u]:
            dfs(u, -1)

    result = [u for u in range(V) if is_articulation[u]]
    if not result:
        return [-1]
    return sorted(result)
